const moreGalleryItems = [['front-steps.jpg','A warm arrival','Steps, entry &amp; planting'],['courtyard.jpg','City garden','Courtyard &amp; wall texture'],['tree-lighting.jpg','The canopy','Mature tree uplighting'],['hillside-steps.jpg','The hillside route','Sloped path &amp; stone walls'],['tudor-home.jpg','Evening character','Tudor facade &amp; garden'],['wooded-deck.jpg','The wooded deck','Deck, steps &amp; trees'],['driveway.jpg','Welcome from the drive','Driveway &amp; entrance'],['fixture-detail.jpg','Small details','Fixture &amp; garden edge']];
const extraGalleryItems = [['shadyside-brick-home.jpg','Shadyside brick','Facade & garden'],['squirrel-hill-stone-home.jpg','Squirrel Hill stone','Stone & pathway'],['mt-lebanon-tudor.jpg','Tudor twilight','Timber & planting'],['victorian-entry.jpg','The city arrival','Brick steps & entry'],['garden-stone-steps.jpg','Garden passage','Steps & woodland'],['bluestone-patio.jpg','Dinner outdoors','Patio & planting'],['front-porch.jpg','The warm porch','Porch & path'],['brick-courtyard.jpg','Courtyard after dark','Walls & maple'],['oak-uplighting.jpg','The old oak','Tree canopy'],['driveway-lighting.jpg','Arrival by car','Drive & entry'],['south-side-garden.jpg','Small urban garden','Brick & vines'],['hillside-deck.jpg','The overlook','Deck & steps'],['retaining-wall.jpg','Stone terrain','Wall & grade'],['modern-home.jpg','A modern line','Grasses & path'],['craftsman-home.jpg','Craftsman character','Stone & porch'],['pergola.jpg','Garden gathering','Pergola & seating'],['garden-bed.jpg','Little points of light','Planting beds'],['wooded-stairway.jpg','The wooded climb','Stairs & trees'],['stone-entry.jpg','At the front door','Entry & stone'],['pool-garden.jpg','Water at dusk','Poolside garden'],['birch-path.jpg','Among birches','Gravel & trees'],['winter-home.jpg','Winter glow','Evergreens & snow']];
