const galleryFull = gallery.replace('</div></div></section>'+cta,[...moreGalleryItems,...extraGalleryItems].map(([img,title,caption])=>`<article class="gallery-page-item"><img src="assets/images/${img}" alt="Illustrative concept of ${title.toLowerCase()} landscape lighting in a Pittsburgh-style setting" loading="lazy"><h2>${title}</h2><p>${caption} · illustrative concept</p></article>`).join('')+'</div></div></section>'+cta).replace('A feeling you can almost step into.','Thirty-six ways to see the night differently.');

const aboutExtra = `<section class="content-section alt"><div class="container editorial-split"><img src="assets/images/craftsman-home.jpg" alt="Illustrative Craftsman home landscape lighting concept" loading="lazy"><div><div class="eyebrow">A home-first approach</div><h2 class="display section-title">Designed for the way you arrive, gather, and unwind.</h2><p class="body-copy">Every home has its own evening rhythm. The front walk is an arrival. A porch is a pause. A patio is a place to stay. Lumascapes thinks about those experiences before deciding where light belongs.</p><p class="body-copy">Pittsburgh homes bring particular character to this work: brick and stone, hillsides, mature trees, narrow city gardens, and deep suburban yards. Lighting should respond to the real property in front of us rather than a fixed pattern.</p><div class="bullet-columns"><div><strong>See the whole view</strong><p>Architecture, planting, and movement are part of one nighttime composition.</p></div><div><strong>Leave room for night</strong><p>Warmth, restraint, and shadow help the important details stand out.</p></div></div></div></div></section><section class="content-section"><div class="container"><div class="content-head"><div class="eyebrow">Where to begin</div><h2 class="display section-title">Bring us the place you want to change.</h2><p class="body-copy">You do not need to know fixture names or have a complete design. Tell us which area you want to see differently and how you use it after sunset. We can discuss the possibilities for design, installation, or service.</p></div><div class="feature-cards"><article class="feature-card"><img src="assets/images/victorian-entry.jpg" alt="Illustrative entry lighting" loading="lazy"><div class="feature-card-body"><div class="eyebrow">01</div><h3>Start at the front</h3><p>Make the approach and the architecture feel like one welcoming view.</p><a class="text-link" href="architectural-lighting-pittsburgh.html">Explore architecture ↗</a></div></article><article class="feature-card"><img src="assets/images/pergola.jpg" alt="Illustrative pergola lighting" loading="lazy"><div class="feature-card-body"><div class="eyebrow">02</div><h3>Stay a little longer</h3><p>Give patios, decks, and garden seating room to feel inviting after dark.</p><a class="text-link" href="patio-lighting-pittsburgh.html">Explore outdoor living ↗</a></div></article><article class="feature-card"><img src="assets/images/fixture-detail.jpg" alt="Illustrative outdoor lighting fixture" loading="lazy"><div class="feature-card-body"><div class="eyebrow">03</div><h3>Care for the effect</h3><p>Talk through changes to an existing lighting system as the landscape evolves.</p><a class="text-link" href="landscape-lighting-service-pittsburgh.html">Explore service ↗</a></div></article></div></div></section>`;
const aboutFull = about.replace(cta,aboutExtra+cta);
const contactExtra = `<section class="content-section alt"><div class="container"><div class="content-head"><div class="eyebrow">Before we talk</div><h2 class="display section-title">A few helpful details.</h2><p class="body-copy">A short note is enough to begin. If you have photos, these details can make a conversation more specific.</p></div><div class="proof-strip"><div><strong>Where is the property?</strong><span>Share your town or neighborhood so service availability can be confirmed.</span></div><div><strong>What should change?</strong><span>Tell us about a dark path, a patio you want to use more, or a facade you love.</span></div><div><strong>What exists now?</strong><span>Let us know if there is an existing lighting system, recent landscaping, or future construction.</span></div></div><p class="body-copy" style="margin-top:45px;max-width:760px">Photos from the street, the main entrance, and the outdoor space you use most are a useful starting point. A quick evening photo can show what currently feels too dark, too bright, or disconnected.</p></div></section>`;
const contactFull = contact+contactExtra;

const serviceData = [
  {slug:'architectural-lighting-pittsburgh.html',name:'Architectural Landscape Lighting',short:'Architectural',hero:'tudor-home.jpg',eyebrow:'Architectural lighting / Pittsburgh',headline:'Give your home a presence after dark.',lead:'Warm architectural lighting can reveal the texture, form, and character of a Pittsburgh home without overwhelming the night.',intro:'Stone, brick, timber, and thoughtful details deserve more than a bright fixture at the front door. Architectural landscape lighting uses placement and restraint to reveal those details from the curb and from the landscape around them.',images:['stone-home.jpg','brick-home.jpg','driveway.jpg'],sections:[['Start with the architecture','Every home has its own rhythm. An entry arch might be the natural focal point; another property may call for a softer wash across brick or stone. A balanced design considers where the viewer stands, how the light reaches a surface, and what remains in shadow. The result should feel intentional from several angles, not only in a single photograph.'],['Connect the house to the landscape','Architecture and plantings look best when they belong to the same composition. Illuminating a tree canopy or a textured wall can add depth beyond the front facade. Paths and steps then lead the eye through the scene while making the route easier to follow.'],['Think beyond the first night','Landscapes grow, seasons change, and fixtures may need attention. A lighting plan should be easy to revisit as trees mature or the way you use the property changes. Lumascapes lists service as part of its offering, so an existing design can be discussed along with a new one.']],faqs:[['Will uplighting make my home too bright?','It does not have to. Fixture placement, beam spread, and aiming can create a soft, selective effect rather than blanket brightness.'],['Does architectural lighting work on brick or stone?','Both can respond beautifully to directional light. The right approach depends on the surface texture, color, and viewing angle.'],['Can trees be part of the design?','Yes. Lighting a tree or planting can give the view depth and keep the house from feeling isolated against a dark yard.']]},
  {slug:'pathway-lighting-pittsburgh.html',name:'Pathway and Step Lighting',short:'Paths & steps',hero:'hillside-steps.jpg',eyebrow:'Pathway lighting / Pittsburgh',headline:'Make the way home feel effortless.',lead:'Path and step lighting can guide movement, give a property visual rhythm, and create a gentler welcome after sunset.',intro:'A path is more than a line from the driveway to the front door. In the evening it becomes part of the experience of arriving home. A thoughtful mix of path lights, step lights, and nearby landscape accents can make the route clear without a row of glaring fixtures.',images:['front-steps.jpg','walkway.jpg','driveway.jpg'],sections:[['Light the route, not every inch','Good path lighting reveals the next step and the direction of travel. That often means focusing on turns, level changes, edges, and transitions rather than trying to cover every square foot equally. The surrounding landscape can provide visual cues too.'],['Work with Pittsburgh terrain','Many Pittsburgh-area properties include slopes, steps, retaining walls, and established planting. Those features can make an entry memorable, but they also change how light is seen from above and below. A design should be evaluated from the street, the driveway, the walk, and the doorway.'],['Keep fixtures part of the landscape','Fixture scale and placement matter during daylight as well as at night. The goal is to support the path and the architecture while avoiding an overly repetitive look. As planting grows, occasional adjustments may help preserve the original effect.']],faqs:[['How far apart should path lights be?','There is no one spacing rule for every property. Path shape, fixture output, nearby planting, and steps all affect the layout.'],['Are step lights and path lights the same?','They serve related purposes but create different effects. Step lights focus on a level change; path lights often illuminate the walking surface and nearby planting.'],['Can lighting be added to an existing walkway?','Often, yes. The available layout depends on access, existing materials, and the route for wiring. A site conversation is the right first step.']]},
  {slug:'patio-lighting-pittsburgh.html',name:'Patio and Outdoor Living Lighting',short:'Patios & outdoor living',hero:'patio.jpg',eyebrow:'Patio lighting / Pittsburgh',headline:'Let your evenings linger.',lead:'Layered patio and garden lighting can make outdoor spaces feel welcoming after dinner, after sunset, and across the changing seasons.',intro:'A patio should feel inviting whether you are hosting friends or stepping outside for a quiet moment. Lighting can define where people gather, reveal the route back to the house, and give planting or stone walls a soft presence at night.',images:['courtyard.jpg','wooded-deck.jpg','terrace.jpg'],sections:[['Build an outdoor room with layers','A patio may need gentle ambient light, attention to steps, and accents around the edges. Each layer has a different job. Together they can create a sense of place without filling every corner with brightness.'],['Connect the patio to the garden','A small tree, wall, or planting bed just beyond the seating area can give the view depth. Lighting beyond the patio edge can also make the space feel larger and more connected to the rest of the property.'],['Design for real evenings','Consider where people enter, where they sit, and what they see from inside the home. Glare at eye level can interrupt an otherwise beautiful scene. A thoughtful plan keeps fixtures discreet and aims light toward the surfaces and moments that matter.']],faqs:[['Can a patio be lit without making it feel harsh?','Yes. Warm, layered light and careful aiming can preserve a relaxed mood while making the area more usable.'],['Can lighting include a deck and nearby trees?','Those spaces can be considered together so the deck does not feel like a bright island against a dark landscape.'],['What if my patio is small?','Smaller spaces often benefit from restraint. A few well-chosen points of light can create atmosphere and clarify the route through the space.']]},
  {slug:'landscape-lighting-service-pittsburgh.html',name:'Landscape Lighting Service',short:'Lighting service',hero:'fixture-detail.jpg',eyebrow:'Lighting service / Pittsburgh',headline:'Keep the effect you love.',lead:'Outdoor lighting lives in a changing landscape. Service can help an existing system continue to look and function the way it should.',intro:'Even a strong lighting design can need attention over time. Plantings grow, fixtures move, connections age, and the way you use an outdoor space can change. Lumascapes offers landscape lighting service for Pittsburgh-area homeowners who want to revisit an existing system.',images:['tree-lighting.jpg','front-steps.jpg','stone-home.jpg'],sections:[['Start with what is happening now','Are some fixtures dark? Has the balance changed as trees and shrubs grew? Does one area feel too bright while another feels forgotten? Describe the system and what you notice, and we can discuss the appropriate next step.'],['Adjust the design as the landscape changes','Outdoor lighting is part of a living setting. A fixture that once highlighted a young tree may need to be repositioned later. A patio addition or a new path may call for the lighting plan to expand or shift.'],['Preserve the whole composition','Service is about more than a single fixture. It is also an opportunity to check whether the overall effect still feels coherent from the spaces you use most: the street, the walkway, and the view from inside.']],faqs:[['Can Lumascapes look at a system someone else installed?','Tell us about the existing system when you reach out. We can discuss its condition and whether it is a fit for service.'],['What information should I send?','Your town, the age of the system if known, a short description of the issue, and photos if available are helpful starting points.'],['Can my current lighting design be refreshed?','Potentially. An update may involve adjustments, replacement of individual elements, or a broader redesign depending on the condition and goals.']]}
];
serviceData.push(
  {slug:'low-voltage-lighting-installation-pittsburgh.html',name:'Low-Voltage Lighting Installation',short:'Installation',hero:'garden-bed.jpg',eyebrow:'Lighting installation / Pittsburgh',headline:'Thoughtful light, carefully placed.',lead:'Low-voltage installation turns an evening concept into a connected outdoor lighting system for your home.',intro:'The best installations begin with design intent: what should the house look like from the street, where should people move comfortably, and which outdoor spaces should invite them to stay?',images:['fixture-detail.jpg','front-porch.jpg','driveway-lighting.jpg'],sections:[['Plan the whole system','Fixture choices, power routes, controls, and access for future service should be considered as one system. A beautiful nighttime effect depends on how these pieces work together on your specific property.'],['Install for the setting','Planting beds, stonework, steps, slopes, and existing utilities all influence installation. A careful conversation about the property helps determine practical fixture positions and wiring routes.'],['Review the effect after dark','The final scene should be viewed from the arrival route, the outdoor spaces you use, and the main windows. Small aiming changes can make a large difference.']],faqs:[['Can an existing system be expanded?','Sometimes. The condition and capacity of the current system need to be understood first.'],['How do I prepare?','Share your goals, town, and photos of the property, including any existing lighting.'],['Do I need to choose fixtures first?','Begin with the effect you want. Fixture selection follows the design and site conditions.']]},
  {slug:'tree-lighting-pittsburgh.html',name:'Tree Uplighting',short:'Trees',hero:'oak-uplighting.jpg',eyebrow:'Tree lighting / Pittsburgh',headline:'Let the canopy become part of the evening.',lead:'Tree lighting can give a garden depth, frame an entry, and make the view from inside feel connected to the landscape.',intro:'Mature trees are part of the character of many Pittsburgh properties. Lighting can reveal trunk texture, branching, and canopy without making the yard uniformly bright.',images:['tree-lighting.jpg','birch-path.jpg','oak-uplighting.jpg'],sections:[['Choose the view first','A tree can read differently from the street, patio, and living-room window. The design starts with the viewpoint that matters most and the role the tree plays in the whole scene.'],['Consider species and shape','An oak canopy, a birch grove, and a small Japanese maple need different approaches. Branching, foliage density, and height affect the beam and fixture position.'],['Plan for growth and seasons','Trees change. Aiming may need adjustment as branches expand, while winter can reveal an entirely different silhouette.']],faqs:[['Can one fixture light a large tree?','It depends on the size and desired effect. A large canopy may need a more layered approach.'],['Will the fixture be visible in daytime?','Placement can make a fixture visually quiet, though exact options depend on the planting bed.'],['Can tree lights work with path lights?','Yes. The two can create foreground and background layers when designed together.']]},
  {slug:'garden-lighting-pittsburgh.html',name:'Garden and Planting Lighting',short:'Gardens',hero:'garden-bed.jpg',eyebrow:'Garden lighting / Pittsburgh',headline:'Give the garden an after-dark life.',lead:'Subtle garden lighting reveals texture, creates depth, and connects planting to the home and outdoor living areas.',intro:'A garden is never static. Flowering beds, grasses, shrubs, and small trees change with weather and season. Lighting should be designed for that movement and growth.',images:['garden-bed.jpg','brick-courtyard.jpg','birch-path.jpg'],sections:[['Find the structure','Start with the permanent elements: walls, paths, larger shrubs, and specimen trees. They carry the scene when seasonal flowers are gone.'],['Use contrast carefully','A softly lit border looks more natural when some leaves and surfaces remain in shadow. Overlighting can remove the very texture the garden offers.'],['Leave room to adjust','As plants fill in, fixtures may need cleaning or re-aiming. Service access is part of a practical long-term design.']],faqs:[['Will fixtures show in the daytime?','Discreet placement can reduce visual clutter, depending on the bed and access.'],['Can lighting work in a small garden?','Yes. A small space often benefits from a few carefully chosen accents.'],['What happens as plants grow?','The scene should be reviewed periodically and adjusted when foliage blocks the intended effect.']]},
  {slug:'deck-lighting-pittsburgh.html',name:'Deck Lighting',short:'Decks',hero:'hillside-deck.jpg',eyebrow:'Deck lighting / Pittsburgh',headline:'Bring warmth to every level.',lead:'Deck lighting can clarify steps and edges while keeping the gathering space calm and inviting.',intro:'A deck is often the bridge between house and landscape. Good lighting considers the stairs, seating area, view beyond the railing, and the way the deck feels from inside.',images:['wooded-deck.jpg','hillside-deck.jpg','pergola.jpg'],sections:[['Make transitions readable','Stairs and changes in level deserve attention, especially on Pittsburgh hillsides. Light should help people understand the route without creating sharp glare.'],['Light beyond the deck','A few landscape accents beyond the railing can keep the deck from feeling like a bright island against a dark yard.'],['Respect the gathering space','Think about eye level when seated, where people enter, and whether a dining area needs a different quality of light than quiet seating.']],faqs:[['Can deck lights be added later?','Possible approaches depend on the deck structure, access, and existing electrical setup.'],['Are step lights enough?','They may help navigation, while surrounding lighting can provide atmosphere and depth.'],['Can trees be included?','Yes, if the tree view supports the overall composition.']]},
  {slug:'driveway-lighting-pittsburgh.html',name:'Driveway and Arrival Lighting',short:'Driveways',hero:'driveway-lighting.jpg',eyebrow:'Driveway lighting / Pittsburgh',headline:'Make the arrival feel complete.',lead:'Driveway lighting can guide the approach and connect the entry, landscape, and architecture into one welcoming nighttime view.',intro:'The view from a car is different from the view on foot. Driveway lighting should help people read the approach while keeping the home and garden visually balanced.',images:['driveway.jpg','driveway-lighting.jpg','stone-entry.jpg'],sections:[['Map the approach','Turns, planting islands, walls, and where visitors park all influence useful lighting positions. A straight row of bright fixtures rarely tells the whole story.'],['Connect to the front walk','The transition from vehicle to walkway should feel continuous. Lighting can move attention from the drive toward the entry.'],['Watch glare from the street','Low fixtures and broad beams can be distracting from a driver’s viewpoint if aimed poorly. Review the scene at night from the actual approach.']],faqs:[['Does every driveway edge need a fixture?','No. Turns and transitions may be more important than continuous illumination.'],['Can landscaping provide some of the light?','Tree and wall accents can offer visual cues alongside dedicated route lighting.'],['Can this be a first project phase?','Yes. An arrival-focused project can be planned with future garden or patio work in mind.']]},
  {slug:'step-lighting-pittsburgh.html',name:'Outdoor Step Lighting',short:'Steps',hero:'wooded-stairway.jpg',eyebrow:'Step lighting / Pittsburgh',headline:'A clear path through every change in level.',lead:'Outdoor step lighting brings attention to transitions while preserving the mood of the landscape.',intro:'Pittsburgh properties often include front steps, sloped gardens, decks, and retaining walls. Their routes deserve lighting that is useful and visually quiet.',images:['front-steps.jpg','wooded-stairway.jpg','retaining-wall.jpg'],sections:[['See the whole stair sequence','A single bright point may leave alternating dark treads. Consider how the full route reads from both directions and where people turn or pause.'],['Fit the materials','Stone, wood, brick, and concrete support different fixture locations. Existing construction and access affect what can be installed.'],['Blend with nearby light','Step lights should work with path and garden lighting so the transition feels part of the property rather than an isolated strip of brightness.']],faqs:[['Should every step have a light?','The layout depends on the stairs and desired effect. The goal is a readable route, not a fixed count.'],['Can existing stone steps be lit?','Options depend on the stonework and access for installation.'],['Will step lights be harsh?','Careful fixture selection and aiming can create a restrained effect.']]}
);

const detailPage = d => `${pageHero(d.eyebrow,d.headline,d.lead,d.hero)}<section class="container article-layout"><article class="rich-copy"><div class="breadcrumbs"><a href="services.html">Services</a><span>/</span><span>${d.short}</span></div><h2>${d.name} for Pittsburgh-area homes</h2><p>${d.intro}</p><p>Every property and project is different. Our conversation begins with what you want to see, how you use the space, and which parts of the home or landscape deserve attention after dark.</p><img class="article-image" src="assets/images/${d.images[0]}" alt="Illustrative concept related to ${d.name.toLowerCase()}" loading="lazy">${d.sections.map(([h,p])=>`<h3>${h}</h3><p>${p}</p>`).join('')}<blockquote class="pullquote">The best lighting gives every evening a more considered point of view.</blockquote><h3>What a first conversation can cover</h3><ul><li>The spaces you want to use, highlight, or navigate after sunset</li><li>How the lighting should look from the street and from inside the home</li><li>Whether an existing system is present and what you would like to change</li><li>Your location in the Pittsburgh area and the next practical step</li></ul><div class="mini-gallery">${d.images.map(img=>`<img src="assets/images/${img}" alt="Illustrative ${d.short.toLowerCase()} lighting concept" loading="lazy">`).join('')}</div><h3>Common questions</h3>${d.faqs.map(([q,a])=>`<h3>${q}</h3><p>${a}</p>`).join('')}<p>See more ideas in the <a href="pittsburgh-landscape-lighting-guide.html">Pittsburgh landscape lighting guide</a>, or <a href="contact.html">tell us about your property</a>.</p></article><aside class="article-aside"><div class="eyebrow">Explore more</div><h3>Lighting by purpose</h3><a href="architectural-lighting-pittsburgh.html">Architectural lighting ↗</a><a href="pathway-lighting-pittsburgh.html">Pathway &amp; step lighting ↗</a><a href="patio-lighting-pittsburgh.html">Patio &amp; outdoor living ↗</a><a href="landscape-lighting-service-pittsburgh.html">Service &amp; refresh ↗</a><a href="gallery.html">See all 36 visual concepts ↗</a><a href="contact.html">Contact Lumascapes ↗</a></aside></section>${cta}`;

const guide = `${pageHero('The Pittsburgh lighting guide','A better view of outdoor lighting.','The questions, choices, and design details worth considering before a landscape lighting project.','wooded-deck.jpg')}<section class="container article-layout"><article class="rich-copy"><div class="breadcrumbs"><a href="index.html">Home</a><span>/</span><span>Lighting guide</span></div><h2>How to think about landscape lighting in Pittsburgh</h2><p>Outdoor lighting is often described in terms of fixtures: path lights, uplights, step lights, and accents. Homeowners experience it differently. They notice whether the front walk feels welcoming, whether a patio invites one more hour outside, and whether the house still has character after the sun goes down.</p><p>A useful plan starts with those experiences. Then it considers the architecture, terrain, planting, and everyday routes through the property. This guide lays out the main decisions to discuss before design and installation.</p><img class="article-image" src="assets/images/hillside-steps.jpg" alt="Illustrative Pittsburgh hillside path lighting concept" loading="lazy"><h3 id="goals">1. Decide what the light should do</h3><p>Most homes benefit from a mix of three goals: reveal the home's best features, make movement around the property more comfortable, and create atmosphere where people spend time. The balance is personal. A formal front elevation may call for architectural accents, while a family that uses a back patio every night may prioritize that space first.</p><p>Write down the places you care about from both inside and outside the home. A view from a living-room window can matter as much as curb appeal from the street.</p><h3 id="layers">2. Build layers, not a wall of brightness</h3><p>Light becomes more interesting when some surfaces are visible and others remain quiet. A tree canopy, a textured wall, and a path can form three distinct layers. Floodlighting everything equally often removes that depth. A thoughtful design uses fixture placement and direction to create a sequence of views.</p><p>Warm light can be especially inviting on brick, stone, wood, and planting. The exact effect depends on the materials, surroundings, and the look you want.</p><div class="mini-gallery"><img src="assets/images/tudor-home.jpg" alt="Illustrative architectural lighting concept" loading="lazy"><img src="assets/images/tree-lighting.jpg" alt="Illustrative tree lighting concept" loading="lazy"><img src="assets/images/courtyard.jpg" alt="Illustrative courtyard lighting concept" loading="lazy"></div><h3 id="paths">3. Study the routes through the property</h3><p>Walk the property after dark. Notice turns, level changes, and places where you pause. Pittsburgh-area homes can have varied grades, steps, and retaining walls. Those features can be beautiful, but they also influence where light is useful and how glare appears from different heights.</p><p>The best path lighting is not necessarily a perfectly spaced line of identical fixtures. It can combine a few path lights with step illumination and nearby landscape accents, depending on the setting.</p><h3 id="living">4. Design the spaces where evenings happen</h3><p>A patio, deck, or garden seating area should have enough light to feel comfortable without losing its evening mood. Think about arrivals and exits, conversation areas, the surrounding view, and what the space looks like from the house. Lighting a feature beyond the patio can help the outdoor room feel connected to the whole landscape.</p><h3 id="system">5. Think about the system over time</h3><p>Low-voltage systems use a transformer and connected fixtures, but design quality depends on much more than choosing equipment. Placement, aiming, wire routes, future planting growth, and access for service all matter. Ask how an existing system could be adjusted later if the landscape changes.</p><h3 id="questions">Questions to bring to your first conversation</h3><ul><li>Which spaces do you use most after sunset?</li><li>What parts of the home or garden should stand out?</li><li>Where are the steps, turns, or transitions that deserve attention?</li><li>What views matter from inside the home?</li><li>Is there an existing lighting system to retain or refresh?</li><li>Which nearby town or neighborhood is the property in?</li></ul><p>Explore <a href="services.html">Lumascapes' lighting services</a>, browse the <a href="gallery.html">illustrative concept gallery</a>, or <a href="contact.html">start a conversation</a> about your Pittsburgh-area property.</p></article><aside class="article-aside"><div class="eyebrow">In this guide</div><h3>Jump to a topic</h3><a href="#goals">Define your goals ↗</a><a href="#layers">Design with layers ↗</a><a href="#paths">Plan paths and steps ↗</a><a href="#living">Light outdoor living ↗</a><a href="#system">Think long term ↗</a><a href="#questions">Questions to ask ↗</a><a href="contact.html">Talk to Lumascapes ↗</a></aside></section>${cta}`;

const privacyTerms = `${pageHero('Privacy & terms','The details behind this website.','How to use the site and what to expect when you contact Lumascapes.','tree-lighting.jpg')}<section class="container article-layout"><article class="rich-copy"><div class="breadcrumbs"><a href="index.html">Home</a><span>/</span><span>Privacy &amp; Terms</span></div><h2>Privacy</h2><p>This website does not store information you type into the contact form. Submitting the form prepares a text message in your device's messaging app; you review and send the message yourself. Standard messaging and carrier practices may apply once you send it.</p><p>Calling, texting, or messaging Lumascapes through Instagram may share the information you choose to provide with those services and with Lumascapes. Do not send sensitive personal information through the website.</p><p>This site uses basic browser code and publicly hosted files. It does not currently use an advertising pixel or analytics tracker. External sites linked from this website have their own privacy practices.</p><h2>Website terms</h2><p>Content on this website is for general information and inspiration. Design ideas, availability, and project details depend on a conversation about your property. Nothing on this site is a quote, warranty, or promise of a specific result.</p><h2>Images and visual concepts</h2><p>Some images on this website are AI-generated visual concepts created to illustrate possible landscape lighting moods and settings. They are not photographs of completed Lumascapes installations. Lumascapes plans to add real project photography as it becomes available. Captions in the gallery identify these images as illustrative concepts.</p><h2>Contact</h2><p>For questions about this website or a lighting project, <a href="contact.html">contact Lumascapes</a> or call <a href="tel:+14122568351">(412) 256-8351</a>.</p></article><aside class="article-aside"><div class="eyebrow">Explore</div><h3>Helpful pages</h3><a href="services.html">Services ↗</a><a href="gallery.html">Gallery ↗</a><a href="contact.html">Contact ↗</a></aside></section>`;


const slugify = s => s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const categoryUrl = c => `journal-${c.slug}.html`;
