const journalCard = (href,title,copy) => `<a href="${href}"><span class="eyebrow">Explore the topic</span><strong>${title}</strong><span>${copy}</span></a>`;
let galleryLinkIndex=0;
const galleryLinked = galleryFull.replace(/<article class="gallery-page-item">[\s\S]*?<\/article>/g, card => { const item=allGalleryItems[galleryLinkIndex++]; return `<a class="gallery-page-link" href="concept-${slugify(item[1])}.html">${card}</a>`; });
const journalHome = `${pageHero('The Lumascapes journal','Better evenings begin with better ideas.','Practical guides to landscape lighting design, installation, service, and Pittsburgh property conditions.','shadyside-brick-home.jpg')}<section class="container content-section"><div class="content-head"><div class="eyebrow">Explore by intention</div><h2 class="display section-title">A library for every decision.</h2><p class="body-copy">Start with the part of your home or landscape you care about. Each collection answers a different set of questions, from architectural light and path safety to service and project planning.</p></div><div class="guide-index">${categories.map(c=>journalCard(categoryUrl(c),c.name,c.intro)).join('')}</div></section>${cta}`;
const categoryBody = c => `${pageHero('Journal / '+c.name,c.name+' ideas for after dark.',c.intro,c.image)}<section class="container content-section"><div class="content-head"><div class="eyebrow">Eight focused guides</div><h2 class="display section-title">Choose the question that fits your project.</h2><p class="body-copy">These articles are planning resources for Pittsburgh-area homeowners. A property-specific design still begins with a conversation and a look at the setting.</p></div><div class="guide-index">${c.topics.map(t=>journalCard(topicUrl(c,t),t[0],t[1])).join('')}</div><p class="body-copy" style="margin-top:42px"><a class="text-link" href="journal.html">All topics ↗</a></p></section>${cta}`;
const topicBody = (c,t,i) => `${pageHero('Pittsburgh lighting guide / '+c.name,t[0]+'.',t[1],c.image)}<section class="container article-layout"><article class="rich-copy"><div class="breadcrumbs"><a href="journal.html">Journal</a><span>/</span><a href="${categoryUrl(c)}">${c.name}</a><span>/</span><span>${t[0]}</span></div><h2>${t[0]} for Pittsburgh-area homes</h2><p>${c.intro}</p><p>${t[1]} The best answer depends on the architecture, planting, grade, and the places from which you see the scene each evening. Begin by naming the effect you want, then consider what fixture placement would create it.</p><img class="article-image" src="assets/images/${c.image}" alt="Illustrative ${t[0].toLowerCase()} concept for a Pittsburgh-style property" loading="lazy"><h3>What to notice on your property</h3><p>${t[2]} Walk the area after dark and note where you approach, pause, or look through a window. A design that appears balanced in a daytime drawing may feel different at night because surrounding areas fall into shadow.</p><p>Notice surfaces that can reflect or absorb light, nearby trees that may grow into a beam, and any view toward a neighbor. These details help make the finished scene comfortable as well as beautiful.</p><h3>How to discuss the design</h3><p>Show the places you want to use and the view you want to improve. Ask what each proposed light is doing in the composition. For ${t[0].toLowerCase()}, that conversation should connect the specific feature with the house, the garden, and any route through the space.</p><p>Consider how the scene may change over time. Plants grow, seasons shift, and fixtures sometimes need to be adjusted. A plan with service access in mind is easier to keep looking intentional.</p><h3>A practical next step</h3><p>Take a few photographs from the street, the main route, and the most important indoor view. Share them with a short description of what currently feels dark, too bright, or unfinished. That gives a lighting designer a more useful starting point than a fixture count alone.</p><p>Explore <a href="${categoryUrl(c)}">more ${c.name.toLowerCase()} guides</a>, review <a href="services.html">Lumascapes' services</a>, or <a href="contact.html">tell us about your property</a>.</p></article><aside class="article-aside"><div class="eyebrow">Keep exploring</div><h3>${c.name}</h3>${c.topics.filter(x=>x!==t).slice(0,5).map(x=>`<a href="${topicUrl(c,x)}">${x[0]} ↗</a>`).join('')}<a href="${categoryUrl(c)}">All ${c.name.toLowerCase()} guides ↗</a><a href="contact.html">Contact Lumascapes ↗</a></aside></section>${cta}`;
const conceptBody = (item,index) => {const [img,title,caption]=item;const related=allGalleryItems.filter(x=>x!==item).slice((index*3)%allGalleryItems.length,(index*3)%allGalleryItems.length+3);return `${pageHero('Visual idea / Pittsburgh landscape lighting',title+'.',caption+' in a Pittsburgh-style evening setting.',img)}<section class="container article-layout"><article class="rich-copy"><div class="breadcrumbs"><a href="gallery.html">Gallery</a><span>/</span><span>${title}</span></div><h2>Look closer at the ${title.toLowerCase()} concept</h2><p>This original visual concept explores how ${caption.toLowerCase()} can shape the feeling of a home after dark. It is an illustrative design concept for inspiration.</p><img class="article-image" src="assets/images/${img}" alt="Illustrative concept of ${title.toLowerCase()} landscape lighting" loading="lazy"><h3>What makes the scene work</h3><p>The strongest outdoor lighting uses a few clear points of attention and leaves room for shadow. In this concept, the relationship between ${caption.toLowerCase()} suggests a layered view rather than a flat wash of brightness.</p><p>For a real property, the effect would need to be adapted to the architecture, materials, planting, and how people move through the space. A fixture that looks right from the sidewalk may need a different aim when viewed from a front window or patio seat.</p><h3>What to ask for your own home</h3><p>Which feature should lead the eye first? Where do you want the route to feel more legible? What should remain quiet after sunset? Those questions are more useful than starting with a fixed number of lights.</p><p>Use this image as a conversation starter. Share photos of your home from the street and from the spaces you use most. Lumascapes can discuss how a lighting approach might translate to your Pittsburgh-area property.</p><p>Browse the <a href="gallery.html">full 36-image gallery</a>, read the <a href="pittsburgh-landscape-lighting-guide.html">lighting guide</a>, or <a href="contact.html">start a conversation</a>.</p></article><aside class="article-aside"><div class="eyebrow">More visual ideas</div><h3>Continue exploring</h3>${related.map(x=>`<a href="concept-${slugify(x[1])}.html">${x[1]} ↗</a>`).join('')}<a href="gallery.html">All concepts ↗</a><a href="contact.html">Contact Lumascapes ↗</a></aside></section>${cta}`};

